def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a
    space-separated string.
    """
    if not hasattr(parser, "_actions"):
        return ""

    flags = []
    for action in parser._actions:
        # action.option_strings holds a list of the option strings for that action
        if getattr(action, "option_strings", None):
            flags.extend(action.option_strings)

    # Remove duplicates while preserving original order
    seen = set()
    unique_flags = []
    for f in flags:
        if f not in seen:
            seen.add(f)
            unique_flags.append(f)

    return " ".join(unique_flags)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two characters")
    if number < 0:
        raise ValueError("Number must be non-negative")
    if number == 0:
        s = alphabet[0]
    else:
        digits = []
        while number:
            number, rem = divmod(number, base)
            digits.append(alphabet[rem])
        s = ''.join(reversed(digits))
    if padding is not None:
        if padding < 0:
            raise ValueError("Padding must be non-negative")
        s = s.rjust(padding, alphabet[0])
    return s

