def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess
    import json
    cmd = ["ansible-playbook"]
    if verbose:
        try:
            lvl = int(verbose)
            if lvl > 0:
                cmd.append("-" + "v" * lvl)
        except Exception:
            pass
    if ansible_args:
        for key, value in ansible_args.items():
            if isinstance(value, bool):
                if value:
                    cmd.append(f"--{key}")
            else:
                cmd.append(f"--{key}={value}")
    if extra_vars:
        cmd.append("--extra-vars")
        cmd.append(json.dumps(extra_vars))
    cmd.append(playbook_path)
    try:
        result = subprocess.run(
            cmd,
            cwd=ir_workspace.root_path() if hasattr(ir_workspace, "root_path") else None,
            capture_output=True,
            text=True,
            check=True,
        )
        output = result.stdout
        if ir_plugin and hasattr(ir_plugin, "report"):
            ir_plugin.report(f"Ansible output:\n{output}")
        return output
    except subprocess.CalledProcessError as exc:
        err = exc.stdout + exc.stderr if hasattr(exc, "stdout") else exc.stderr
        if ir_plugin and hasattr(ir_plugin, "report"):
            ir_plugin.report(f"Ansible failed: {err}")
        raise RuntimeError(f"Ansible playbook failed with return code {exc.returncode}\n{err}") from exc

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
       """
        # Attempt to use a predefined mapping of argument types if available
        arg_type_map = getattr(self, "_arg_type_map", {}).get(parser_name, {})
        for key, val in list(values_dict.items()):
            if val is None:
                continue
            # Use explicit type mapping if defined
            if key in arg_type_map:
                target_type = arg_type_map[key]
                try:
                    values_dict[key] = target_type(val)
                except Exception:
                    # Fall back to string if conversion fails
                    values_dict[key] = val
                continue

            # Generic conversion: try bool, int, float in order
            lower = str(val).lower()
            if lower in ("true", "false"):
                values_dict[key] = lower == "true"
            else:
                try:
                    values_dict[key] = int(val)
                except (ValueError, TypeError):
                    try:
                        values_dict[key] = float(val)
                    except (ValueError, TypeError):
                        # Leave as original string
                        values_dict[key] = val
        # No return value needed; values_dict is modified in place.

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    if not isinstance(plugin_dir, dict):
        return {}
    result={}
    def _flatten(d, parent_key=''):
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                _flatten(v, new_key)
            else:
                result[new_key]=v
    _flatten(plugin_dir)
    return result

